    writeByte(MessagesPigeonInteropCodec.typeMap)
    writeSize(map.count)
    for (key, item) in map {
      writeValue(key)
      writeOptional(item)
    }
  }

  mutating func writeMap<K, V>(_ map: [K?: V?]?) {
    guard let map = map else {
      writeByte(MessagesPigeonInteropCodec.typeNull)
      return
