  mutating func writeCustomValue(_ value: Any, type valueType: Any.Type) -> Bool {
    if valueType == SourceKindMessage.self {
      writeByte(129)
      writeValue(Int64((value as! SourceKindMessage).rawValue))
      return true
    }
    if valueType == MediaKindMessage.self {
      writeByte(130)
      writeValue(Int64((value as! MediaKindMessage).rawValue))
      return true
    }
    if valueType == MediaSourceMessage.self {
      writeByte(131)
      writeMediaSourceMessage((value as! MediaSourceMessage))
      return true
    }
    if valueType == PixelSizeMessage.self {
      writeByte(132)
      writePixelSizeMessage((value as! PixelSizeMessage))
      return true
    }
    if valueType == GpsLocationMessage.self {
      writeByte(133)
      writeGpsLocationMessage((value as! GpsLocationMessage))
      return true
    }
    if valueType == MetadataTagMessage.self {
      writeByte(134)
      writeMetadataTagMessage((value as! MetadataTagMessage))
      return true
    }
    if valueType == PngTextChunkMessage.self {
      writeByte(135)
      writePngTextChunkMessage((value as! PngTextChunkMessage))
      return true
    }
    if valueType == ImageMetadataMessage.self {
      writeByte(136)
      writeImageMetadataMessage((value as! ImageMetadataMessage))
      return true
    }
    if valueType == VideoMetadataMessage.self {
      writeByte(137)
      writeVideoMetadataMessage((value as! VideoMetadataMessage))
      return true
    }
    if valueType == AudioMetadataMessage.self {
      writeByte(138)
      writeAudioMetadataMessage((value as! AudioMetadataMessage))
      return true
    }
    if valueType == MediaMetadataMessage.self {
      writeByte(139)
      writeMediaMetadataMessage((value as! MediaMetadataMessage))
      return true
    }
    return false
  }

  mutating func writeCustomValueFallback(_ value: Any) -> Bool {
    if let value = value as? SourceKindMessage {
      writeByte(129)
      writeValue(Int64(value.rawValue))
      return true
    }
    if let value = value as? MediaKindMessage {
      writeByte(130)
      writeValue(Int64(value.rawValue))
      return true
    }
    if let value = value as? MediaSourceMessage {
      writeByte(131)
      writeMediaSourceMessage(value)
      return true
    }
    if let value = value as? PixelSizeMessage {
      writeByte(132)
      writePixelSizeMessage(value)
      return true
    }
    if let value = value as? GpsLocationMessage {
      writeByte(133)
      writeGpsLocationMessage(value)
      return true
    }
    if let value = value as? MetadataTagMessage {
      writeByte(134)
      writeMetadataTagMessage(value)
      return true
    }
    if let value = value as? PngTextChunkMessage {
      writeByte(135)
      writePngTextChunkMessage(value)
      return true
    }
    if let value = value as? ImageMetadataMessage {
      writeByte(136)
      writeImageMetadataMessage(value)
      return true
    }
    if let value = value as? VideoMetadataMessage {
      writeByte(137)
      writeVideoMetadataMessage(value)
      return true
    }
    if let value = value as? AudioMetadataMessage {
      writeByte(138)
      writeAudioMetadataMessage(value)
      return true
    }
    if let value = value as? MediaMetadataMessage {
      writeByte(139)
      writeMediaMetadataMessage(value)
      return true
    }
    return false
  }
}

/// Unwraps optionals that a generic context boxed into `Any`.
