    /// when `name` is omitted), leaving other registrations in place.
    ///
    /// Instances are matched by identity. Does nothing if `api` is not registered.
    ///
    /// Prefers the registration made from the engine that owns `registrar`, and
    /// otherwise removes the registration of `api` under `name` if exactly one engine
    /// holds it.
    static func unregister(api: MediaInfoHostApi, registrar: FlutterPluginRegistrar, name: String = MessagesPigeonInternal.defaultInstanceName) {
      unregister(api: api, engineKey: PigeonEngineKeys.key(for: registrar), name: name)
    }
  #endif

  fileprivate static func register(api: MediaInfoHostApi, engineKey: Int64, name: String) {
    MediaInfoHostApiInstanceTracker.lock.lock()
    defer { MediaInfoHostApiInstanceTracker.lock.unlock() }
    var list = MediaInfoHostApiInstanceTracker.instancesOfMediaInfoHostApi[name] ?? []
    if let index = list.firstIndex(where: { $0.api === api && $0.engineKey == engineKey }) {
      list.append(list.remove(at: index))
    } else {
      let wrapper = MediaInfoHostApiSetup()
      wrapper.engineKey = engineKey
      wrapper.api = api
      list.append(wrapper)
    }
    MediaInfoHostApiInstanceTracker.instancesOfMediaInfoHostApi[name] = list
  }

  fileprivate static func unregister(api: MediaInfoHostApi, engineKey: Int64, name: String) {
    // Removed entries are kept alive until after unlocking so their deinit cannot run while the
    // non-recursive lock is held.
    var displaced: [Any] = []
    do {
      MediaInfoHostApiInstanceTracker.lock.lock()
      defer { MediaInfoHostApiInstanceTracker.lock.unlock() }
      guard var list = MediaInfoHostApiInstanceTracker.instancesOfMediaInfoHostApi[name] else {
        return
      }
      let removeKey: Int64
      if list.contains(where: { $0.api === api && $0.engineKey == engineKey }) {
        removeKey = engineKey
      } else {
        let keys = Set(list.filter { $0.api === api }.map { $0.engineKey })
        guard keys.count == 1, let onlyKey = keys.first else {
          return
        }
        removeKey = onlyKey
      }
      list.removeAll { entry in
        guard let existing = entry.api else {
          return false
        }
        if existing === api && entry.engineKey == removeKey {
          displaced.append(existing)
          displaced.append(entry)
          entry.api = nil
          return true
        }
        return false
      }
      if list.isEmpty {
        MediaInfoHostApiInstanceTracker.instancesOfMediaInfoHostApi.removeValue(forKey: name)
      } else {
