  /// `affinityKey`, then the most recent registration. `Int64.min` means unknown.
  @objc static func pigeonResolveInstance(engineId: Int64, affinityKey: Int64, name: String = MessagesPigeonInternal.defaultInstanceName) -> MediaInfoHostApiSetup? {
    MediaInfoHostApiInstanceTracker.lock.lock()
    defer { MediaInfoHostApiInstanceTracker.lock.unlock() }
    guard let list = MediaInfoHostApiInstanceTracker.instancesOfMediaInfoHostApi[name] else {
      return nil
    }
    if engineId != Int64.min, let match = list.last(where: { $0.engineKey == engineId }) {
      return match
    }
    if affinityKey != Int64.min, let match = list.last(where: { $0.engineKey == affinityKey }) {
      return match
    }
    return list.last
  }

  /// Returns the engine key `instance` was registered with, or `Int64.min` if unknown.
  @objc static func pigeonEngineKey(of instance: MediaInfoHostApiSetup) -> Int64 {
    return instance.engineKey
  }
